merge_ordered

Merge and sort a collection of sorted collections

This works lazily and only keeps one value from each iterable in memory.

>>> list(merge_ordered([1, 3, 5], [2, 4, 6]))
[1, 2, 3, 4, 5, 6]

>>> ''.join(merge_ordered('abc', 'abc', 'abc'))
'aaabbbccc'

The "key" function used to sort the input may be passed as a keyword.

>>> list(merge_ordered([2, 3], [1, 3], key=lambda x: x // 3))
[2, 1, 3, 3]

def merge_ordered(*seqs, **kwargs):
    """ Merge and sort a collection of sorted collections

    This works lazily and only keeps one value from each iterable in memory.

    >>> list(merge_ordered([1, 3, 5], [2, 4, 6]))
    [1, 2, 3, 4, 5, 6]

    >>> ''.join(merge_ordered('abc', 'abc', 'abc'))
    'aaabbbccc'

    The "key" function used to sort the input may be passed as a keyword.

    >>> list(merge_ordered([2, 3], [1, 3], key=lambda x: x // 3))
    [2, 1, 3, 3]
    """
    if len(seqs) == 0:
        return iter([])
    elif len(seqs) == 1:
        return iter(seqs[0])

    key = kwargs.get('key', None)
    if key is None:
        return _merge_sorted_binary(seqs)
    else:
        return _merge_sorted_binary_key(seqs, key)

without_keys

Return a new dict with the given key(s) removed.

New dict has d[key] deleted for each supplied key.
Does not modify the initial dictionary.

>>> without_keys({'x': 1, 'y': 2}, 'y')
{'x': 1}
>>> without_keys({'x': 1, 'y': 2}, 'y', 'x')
{}
>>> without_keys({'x': 1}, 'y') # Ignores missing keys
{'x': 1}

def without_keys(d, *keys, **kwargs):
    """ Return a new dict with the given key(s) removed.

    New dict has d[key] deleted for each supplied key.
    Does not modify the initial dictionary.

    >>> without_keys({'x': 1, 'y': 2}, 'y')
    {'x': 1}
    >>> without_keys({'x': 1, 'y': 2}, 'y', 'x')
    {}
    >>> without_keys({'x': 1}, 'y') # Ignores missing keys
    {'x': 1}
    """
    factory = _get_factory(without_keys, kwargs)
    d2 = factory()

    if len(keys) < len(d) * .6:
        d2.update(d)
        for key in keys:
            if key in d2:
                del d2[key]
    else:
        remaining = set(d)
        remaining.difference_update(keys)
        for k in remaining:
            d2[k] = d[k]
    return d2

yield_last

Return an iterator over the final *n* items of *iterable*.

>>> t = yield_last(3, 'ABCDEFG')
>>> list(t)
['E', 'F', 'G']

def yield_last(n, iterable):
    """Return an iterator over the final *n* items of *iterable*.

    >>> t = yield_last(3, 'ABCDEFG')
    >>> list(t)
    ['E', 'F', 'G']

    """
    try:
        size = len(iterable)
    except TypeError:
        return iter(deque(iterable, maxlen=n))
    else:
        return islice(iterable, max(0, size - n), None)
